  // Configuration des nodes — libellés de champs et aides (lot 21)
  // ⚠️ Schéma de clé DESCRIPTIF (`node.<type>.<champ>.label|help`). Les anciennes
  // clés `node.<type>.fN` restent en place — renuméroter aurait été risqué pour
  // zéro gain. Toute clé AJOUTÉE suit le schéma descriptif : opaque = collisions.
  'node.compare-catalog.taxoColumns.help': 'Taxonomy levels, broadest to finest, separated by ">" (e.g. UNIVERS > FAMILLE > SOUS FAMILLE > PRODUCTGROUP). Leave empty to detect them: the order is then derived from how many distinct values each column holds, and empty columns are dropped.',
  'node.compare-catalog.urlColumn.help': 'Link to the product page on YOUR site — makes the name clickable in the table to check the price. Optional.',
  'node.compare-catalog.watchId.help': 'Leave EMPTY: the monitoring is automatically the workflow\'s own (the same as the workflow\'s "Competitor harvest"). Fill it in only to share one monitoring across several workflows.',
  'node.compare-prices.noSource.help': '"Family" mode: wire every retailer to "competitors". 1 row per product, 1 price column per retailer, best price + gap.',
  'node.cron.afterEnd.help': 'Ideal for a scrape that advances in slices: the next run starts "Every X" AFTER the previous one ends, with no fixed cadence — no overlap, no idle time. The time and day below are ignored in this mode.',
  'node.directed-search.genericSites.help': 'Amazon, Cdiscount, Kramp…: web search by reference + Firecrawl (JS rendering + anti-bot). Requires a Firecrawl key. Costs per reference — start with 1 site to validate.',
  'node.directed-search.descriptionColumn.help': 'E.g. TEXT_VENTE_FR. DECISIVE on an aftermarket parts catalogue: if your item reference is an INTERNAL code, no competitor carries it — only the original refs quoted here ("Origin: …") make the product findable.',
  'node.directed-search.productBudget.help': "Number of products tested per run. Each is searched on every active site. The pass stops by itself at the run deadline and resumes at the next product: a large budget no longer wastes work, it simply fills the window. Concurrency adapts to the number of sites (8 requests in flight overall). ⚠ Each product costs 1 to 2 requests PER SITE — on a paid engine such as Firecrawl, watch your credits.",
  'node.directed-search.watchId.help': 'Leave EMPTY: the monitoring is the workflow\'s own (shared with "Compare catalogue" in the same workflow — the prices found then show up in the dashboard).',
  'node.harvest-competitor.pageBudget.help': 'Listing pages harvested on each run, shared between the sites. A site can RESERVE its own budget (the "pages" field on its card in "Source sites") — useful to throttle a paid competitor without rationing the free ones. ⚠ This is THE throughput ceiling. On a SCHEDULED run (cron), the time window now bounds the pass by itself: this field is only a safety cap, so be generous. On a run started from the browser there is no deadline — this field decides the duration.',
  'node.save-pim.sourceId.help': 'Source ID. If it does not exist in the project, the products will be created but invisible in the source list (to be fixed in phase 2).',
  'node.price-watch.thresholdPct.label': 'Change threshold (%)',
  'node.price-watch.thresholdPct.help': '0 = report every change.',
  'node.price-watch.watchId.help': 'The state (last prices seen) is remembered per identifier — one monitoring per watched list.',
  'node.price-watch.watchId.label': 'Monitoring identifier',
  'node.price-watch.keyColumn.label': 'Key column',
  'node.price-watch.keyColumn.help': 'Identifies each product between two runs (url, sku, ean…).',
  'node.price-watch.valueColumn.label': 'Price column',
  'node.price-watch.valueColumn.help': 'Monitored value (parses "1,299.90 €").',
