  'node.pw-report.label': 'Price monitoring report',
  'node.pw-report.desc': 'Renders the monitoring report as modern HTML: price position, alerts on significant gaps, competitor ranking, exposed families. Wire it to "Send via Gmail" (data port) or "Export to Google Drive".',
  'node.pw-report.title.label': 'Report title',
  'node.pw-report.title.help': 'Shown at the top of the email. E.g. "Price monitoring — week 32".',
  'node.pw-report.compThreshold.label': 'Aggressive competitor threshold (%)',
  'node.pw-report.compThreshold.help': 'A competitor is FLAGGED when their MEDIAN gap sits below your prices by more than this percentage. 5% is a good start: below that, nearly everyone is flagged and the alert stops meaning anything.',
  'node.pw-report.famThreshold.label': 'Exposed family threshold (%)',
  'node.pw-report.famThreshold.help': 'A family is FLAGGED when this share of its products is sold cheaper by at least one competitor. Families with fewer than 5 products are skipped: the ratio means nothing there.',
  'node.pw-report.examples.label': 'Product examples',
  'node.pw-report.examples.help': 'How many products to list as illustration. ⚠ They come from the detailed list, CAPPED to the most undercut ones: they illustrate, they do not measure.',
  'node.pw-report.fileName.label': 'File name (optional)',
  'run.pwReport.noReport': 'No report for monitoring "{watchId}": run "Compare catalogue" before sending the email.',
  'run.pwReport.done': 'Report rendered: {products} matched products, {sites} competitor(s), {size} kB.',
  'node.send-window.label': 'Send window',
  'node.send-window.desc': 'Lets through only within the intended window, and once per period. Place it right before "Send via Gmail": the workflow can run every half-hour without sending forty-eight emails. Outside the window the rest is suspended — the run stays green.',
  'node.send-window.freq.label': 'Frequency',
  'node.send-window.atTime.label': 'Earliest time (HH:MM)',
  'node.send-window.atTime.help': 'Nothing goes out before this time. Leave empty to send on the first pass of an allowed day.',
  'node.send-window.weekdays.label': 'Days (0 = Sunday)',
  'node.send-window.weekdays.help': 'Comma-separated: "1,2,3,4,5" = Monday to Friday. Empty = every day.',
  'node.send-window.tz.label': 'Time zone',
  'node.send-window.tz.help': 'Essential: the cron runs in UTC. Without a zone, "8 am" would go out at 10 am during French summer time. E.g. Europe/Paris.',
  'node.send-window.key.label': 'Cadence key (optional)',
  'node.send-window.key.help': 'Only needed when one workflow carries SEVERAL cadences (e.g. "weekly" and "monthly"): each then keeps its own send memory.',
  'run.sendWindow.closed': 'Send suspended — {reason}',
  'run.sendWindow.open': 'Window open: sending allowed for period {key}.',
